    s = R(4, 10); b = R(1, s - 1); a = s - b;
    return num(s + " " + M + " ___ = " + a, b, ["Скільки треба забрати від " + s + ", щоб лишилось " + a + "?", "Від " + a + " до " + s + " — стільки й забрали."], s + " " + M + " <b>" + b + "</b> = " + a + ".", { calc: s + "-" + a });
