  G.year = function () { return pickOne([G.add20, G.sub20, G.addc, G.subc, G.mulT, G.divT, G.order, G.eq, G.prob2, G.prob2s, G.probx, G.probmd, G.len, G.clock, G.money, G.perim])({ t: [2, 3, 4, 5], max: 100 }); };


  /* =================== АКЦЕНТ НА ЗАДАЧАХ =================== */
